INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'music_exam','stage_types','s_1f9e97c328d9',t.id FROM stage_types t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='music_exam' AND t.source='template' AND t.version=1 AND t.name='常规提升' AND s.pack_version='0.1';
